const FILTER_PARAMS = {
  lmin: 'levelMin', lmax: 'levelMax', emin: 'evMin', emax: 'evMax', role: 'role',
  action: 'action', source: 'source', status: 'status', keyword: 'keyword', owner: 'owner', cost: 'cost'
};

function setHash(push = true) {
  const params = new URLSearchParams();
  params.set('mode', state.mode);
  params.set('view', state.view);
  if (state.scope !== 'all') params.set('scope', state.scope);
  if (state.query) params.set('q', state.query);
  if (state.type !== 'all') params.set('type', state.type);
  if (state.sort !== 'relevance') params.set('sort', state.sort);
  if (state.selectedId) params.set('id', state.selectedId);
  if (state.section) params.set('section', state.section);
  if (state.lessonId) params.set('lesson', state.lessonId);
  if (state.lessonStep) params.set('step', String(state.lessonStep));
  if (state.view === 'hero') { if (state.activeHeroId) params.set('profile', state.activeHeroId); if (state.heroTab !== 'guided') params.set('herotab', state.heroTab); if(state.heroTab==='guided'&&state.heroWizardStep!=='concept')params.set('herostep',state.heroWizardStep); }
  if (state.view === 'director') { params.set('directortab', state.directorTab); if (state.activeEncounterId) params.set('encounter', state.activeEncounterId); }
  if (state.view === 'data') params.set('datatab', state.dataTab);
  for (const [parameter, key] of Object.entries(FILTER_PARAMS)) if (state.filters[key] !== '') params.set(parameter, state.filters[key]);
  if (!state.filters.useSynonyms) params.set('literal', '1');
  const hash = '#' + params.toString();
  if (location.hash === hash) return;
  try { history[push ? 'pushState' : 'replaceState'](null, '', hash); }
  catch { location.hash = hash; }
}

function loadHash() {
  const params = new URLSearchParams(location.hash.replace(/^#/, ''));
  state.mode = params.get('mode') || state.mode;
  state.view = params.get('view') || 'dashboard';
  state.scope = params.get('scope') || 'all';
  state.query = params.get('q') || '';
  state.type = params.get('type') || 'all';
  state.sort = params.get('sort') || 'relevance';
  state.selectedId = params.get('id') || null;
  state.section = params.get('section') || '';
  state.lessonId = params.get('lesson') || '';
  state.lessonStep = Number.parseInt(params.get('step') || '0', 10) || 0;
  if (params.get('profile') && state.heroProfiles.some(hero => hero.id === params.get('profile'))) state.activeHeroId = params.get('profile');
  if (['guided','overview','class','sheet','play','reference','collections'].includes(params.get('herotab'))) state.heroTab = params.get('herotab');
  if(HERO_WIZARD_STEP_IDS.includes(params.get('herostep')))state.heroWizardStep=params.get('herostep');
  if (['monsters','encounters','combat','conditions','power','runner','negotiation','montage'].includes(params.get('directortab'))) state.directorTab = params.get('directortab');
  if (params.get('encounter') && state.encounters.some(item => item.id === params.get('encounter'))) state.activeEncounterId = params.get('encounter');
  if (['exports','vtt','errata','backup','updates'].includes(params.get('datatab'))) state.dataTab = params.get('datatab');
  state.filters = defaultFilters();
  for (const [parameter, key] of Object.entries(FILTER_PARAMS)) if (params.has(parameter)) state.filters[key] = params.get(parameter);
  state.filters.useSynonyms = params.get('literal') !== '1';
  state.resultLimit = 100;
  searchEl.value = state.query;
}

