  document.getElementById('heroSpendRecovery')?.addEventListener('click',()=>{const before=current();session.currentStamina=Math.min(max,before+recovery);session.recoveriesSpent++;save(`Caught Breath and spent a Recovery (Stamina: ${before} → ${session.currentStamina})`);});
