function netEdgeState(edges,banes){const net=Math.max(0,Number(edges)||0)-Math.max(0,Number(banes)||0);return net>=2?{label:'Double edge',modifier:0,shift:1}:net===1?{label:'Edge',modifier:2,shift:0}:net<=-2?{label:'Double bane',modifier:0,shift:-1}:net===-1?{label:'Bane',modifier:-2,shift:0}:{label:'No edge or bane',modifier:0,shift:0};}
