  document.querySelectorAll('[data-runner-squad-acted]').forEach(button=>button.onclick=()=>{const squad=session.squads.find(item=>item.squadId===button.dataset.runnerSquadActed);if(squad){squad.actedThisRound=!squad.actedThisRound;rerender();}});
