  const adjustCreature=(id,amount)=>{const creature=session.creatures.find(item=>item.instanceId===id);if(creature){creature.currentStamina+=Number(amount)||0;rerender();}};
  document.querySelectorAll('[data-creature-stamina]').forEach(button=>button.onclick=()=>adjustCreature(button.dataset.creatureStamina,button.dataset.amount));document.querySelectorAll('[data-creature-custom]').forEach(button=>button.onclick=()=>adjustCreature(button.dataset.creatureCustom,prompt('Stamina adjustment (negative for damage):','-1')));
