  document.querySelectorAll('[data-creature-condition-remove]').forEach(button=>button.onclick=()=>{const creature=session.creatures.find(item=>item.instanceId===button.dataset.creatureConditionRemove);if(creature){creature.conditions=creature.conditions.filter(item=>item.id!==button.dataset.conditionId);rerender();}});
