const NEGOTIATION_ATTITUDES={Hostile:[1,2],Suspicious:[2,2],Neutral:[2,3],Open:[3,3],Friendly:[3,4],Trusting:[3,5]}; // From rule-negotiation-negotiation-starting-attitudes-table.
function startNegotiationSession(setup={}){const attitude=NEGOTIATION_ATTITUDES[setup.attitude]?setup.attitude:'Neutral',[defaultInterest,defaultPatience]=NEGOTIATION_ATTITUDES[attitude],interest=Number.parseInt(setup.interest,10),patience=Number.parseInt(setup.patience,10);return {npcName:String(setup.npcName||'NPC').slice(0,120),attitude,interest:Math.max(0,Math.min(5,Number.isFinite(interest)?interest:defaultInterest)),patience:Math.max(0,Math.min(5,Number.isFinite(patience)?patience:defaultPatience)),motivations:String(setup.motivations||'').split('\n').map(value=>value.trim()).filter(Boolean).slice(0,20),pitfalls:String(setup.pitfalls||'').split('\n').map(value=>value.trim()).filter(Boolean).slice(0,20),log:[]};}
