function renderNegotiationTracker(){const session=state.negotiationSession;if(!session)return `<section class="director-panel tracker-panel"><header class="director-panel-head"><div><h3>Set up a negotiation</h3><p>Interest and Patience defaults come from the published starting-attitude table.</p></div></header><div class="director-panel-body tracker-setup"><label>NPC Name<input id="negotiationNpcName" value=""></label><label>Starting Attitude<select id="negotiationAttitude">${Object.keys(NEGOTIATION_ATTITUDES).map(name=>`<option ${name==='Neutral'?'selected':''}>${esc(name)}</option>`).join('')}</select></label><label>Interest (0–5)<input id="negotiationInterest" type="number" min="0" max="5" value="2"></label><label>Patience (0–5)<input id="negotiationPatience" type="number" min="0" max="5" value="3"></label><label class="wide">Motivations<textarea id="negotiationMotivations" placeholder="One per line"></textarea></label><label class="wide">Pitfalls<textarea id="negotiationPitfalls" placeholder="One per line"></textarea></label><div class="wide director-actions"><button class="director-btn primary" id="startNegotiation">Start Negotiation</button><button class="mini-btn" data-open-source="rule-section-negotiation-negotiation-stats">Negotiation stats</button></div><p class="session-not-persisted wide">This in-progress tracker is session-only and is cleared when the page reloads.</p></div></section>`;return `<section class="director-panel tracker-panel"><header class="director-panel-head"><div><h3>${esc(session.npcName)} — Negotiation</h3><p>${esc(session.attitude)} starting attitude</p></div><button class="director-btn danger" id="resetNegotiation">Reset Negotiation</button></header><div class="director-panel-body"><div class="tracker-stat-grid"><section><button class="tracker-stat-label" data-open-source="rule-section-negotiation-negotiation-stats">Interest</button><strong>${esc(statPips(session.interest))}</strong><span>${esc(session.interest)} / 5</span><div><button class="director-btn" data-negotiation-stat="interest" data-delta="-1">−1 Interest</button><button class="director-btn" data-negotiation-stat="interest" data-delta="1">+1 Interest</button></div></section><section><button class="tracker-stat-label" data-open-source="rule-section-negotiation-negotiation-stats">Patience</button><strong>${esc(statPips(session.patience))}</strong><span>${esc(session.patience)} / 5</span><div><button class="director-btn" data-negotiation-stat="patience" data-delta="-1">−1 Patience</button><button class="director-btn" data-negotiation-stat="patience" data-delta="1">+1 Patience</button></div></section></div><div class="tracker-status"><span>Status</span><strong>${esc(negotiationStatus(session))}</strong><button class="mini-btn" data-open-source="rule-section-negotiation-negotiation-stats">Source</button></div><div class="tracker-notes"><section><h4>Motivations</h4>${session.motivations.map(item=>`<p>${esc(item)}</p>`).join('')||'<p>None recorded.</p>'}</section><section><h4>Pitfalls</h4>${session.pitfalls.map(item=>`<p>${esc(item)}</p>`).join('')||'<p>None recorded.</p>'}</section></div><div class="session-log"><h4>Activity log</h4>${session.log.slice(-10).reverse().map(entry=>`<div><time>${esc(new Date(entry.at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}))}</time><span>${esc(entry.description)}</span></div>`).join('')||'<div class="session-empty">No changes yet.</div>'}</div><p class="session-not-persisted">This in-progress tracker is session-only and is cleared when the page reloads.</p></div></section>`;}
function wireNegotiationTracker(){document.getElementById('negotiationAttitude')?.addEventListener('change',event=>{const values=NEGOTIATION_ATTITUDES[event.target.value]||NEGOTIATION_ATTITUDES.Neutral;document.getElementById('negotiationInterest').value=values[0];document.getElementById('negotiationPatience').value=values[1];});document.getElementById('startNegotiation')?.addEventListener('click',()=>{state.negotiationSession=startNegotiationSession({npcName:document.getElementById('negotiationNpcName').value,attitude:document.getElementById('negotiationAttitude').value,interest:document.getElementById('negotiationInterest').value,patience:document.getElementById('negotiationPatience').value,motivations:document.getElementById('negotiationMotivations').value,pitfalls:document.getElementById('negotiationPitfalls').value});renderDirectorTools();});document.querySelectorAll('[data-negotiation-stat]').forEach(button=>button.onclick=()=>{const session=state.negotiationSession,key=button.dataset.negotiationStat,before=session[key];session[key]=Math.max(0,Math.min(5,before+Number(button.dataset.delta)));appendSessionLog(session,`${key[0].toUpperCase()+key.slice(1)} ${before} → ${session[key]}`);renderDirectorTools();});document.getElementById('resetNegotiation')?.addEventListener('click',()=>{state.negotiationSession=null;renderDirectorTools();});}
