/* ---------- Phase 8: icon legend ---------- */
const ICON_TIP_MAP = {
  '\u2694\ufe0f': 'Melee or ranged strike',
  '\ud83d\udde1': 'Melee strike',
  '\ud83c\udff9': 'Ranged strike',
  '\u2757\ufe0f': 'Triggered / reactive ability',
  '\u2b50\ufe0f': 'Passive trait / upgrade',
  '\u2620\ufe0f': 'Villain action / Malice',
  '\ud83d\udd33': 'Ranged area ability',
  '\u2747\ufe0f': 'Area ability',
  '\ud83d\udc64': 'Self / movement ability',
  '\ud83c\udf00': 'Deactivate (object / terrain)',
  '\u2755': 'Activate (object / terrain)'
};
const ICON_LEGEND_FRAGMENT = "<div class=\"legend-header\"><h2>Ability Icon Legend</h2><button class=\"legend-close\" id=\"legendCloseBtn\" aria-label=\"Close legend\">\u00d7</button></div><div class=\"legend-body\"><div class=\"legend-group\"><div class=\"legend-group-label\">Ability types</div><div class=\"legend-row\"><div class=\"legend-icon\">\ud83d\udde1</div><div class=\"legend-desc\"><strong>Melee strike</strong><span>Targets one or more creatures in melee range.</span></div></div><div class=\"legend-row\"><div class=\"legend-icon\">\ud83c\udff9</div><div class=\"legend-desc\"><strong>Ranged strike</strong><span>Targets one or more creatures at a distance.</span></div></div><div class=\"legend-row\"><div class=\"legend-icon\">\u2694\ufe0f</div><div class=\"legend-desc\"><strong>Melee or ranged strike</strong><span>Can be used at either melee or ranged distance.</span></div></div><div class=\"legend-row\"><div class=\"legend-icon\">\u2747\ufe0f</div><div class=\"legend-desc\"><strong>Area ability</strong><span>Affects every creature or enemy in an area (burst, wall, cube, etc.).</span></div></div><div class=\"legend-row\"><div class=\"legend-icon\">\ud83d\udd33</div><div class=\"legend-desc\"><strong>Ranged area ability</strong><span>An area effect delivered at a range.</span></div></div><div class=\"legend-row\"><div class=\"legend-icon\">\ud83d\udc64</div><div class=\"legend-desc\"><strong>Self / movement ability</strong><span>Affects the creature itself, often a maneuver or repositioning effect.</span></div></div></div><div class=\"legend-group\"><div class=\"legend-group-label\">Timing</div><div class=\"legend-row\"><div class=\"legend-icon\">\u2757\ufe0f</div><div class=\"legend-desc\"><strong>Triggered / reactive ability</strong><span>Used in response to a specified trigger; includes free triggered actions.</span></div></div><div class=\"legend-row\"><div class=\"legend-icon\">\u2b50\ufe0f</div><div class=\"legend-desc\"><strong>Passive trait / upgrade</strong><span>An always-on rule that modifies the creature's behaviour, or an available upgrade.</span></div></div><div class=\"legend-row\"><div class=\"legend-icon\">\u2620\ufe0f</div><div class=\"legend-desc\"><strong>Villain action / Malice</strong><span>A powerful ability available only to Solo monsters, or a Malice-cost Director option.</span></div></div></div><div class=\"legend-group\"><div class=\"legend-group-label\">Object / terrain states</div><div class=\"legend-row\"><div class=\"legend-icon\">\ud83c\udf00</div><div class=\"legend-desc\"><strong>Deactivate</strong><span>This object or terrain feature can be deactivated (trigger-based rule).</span></div></div><div class=\"legend-row\"><div class=\"legend-icon\">\u2755</div><div class=\"legend-desc\"><strong>Activate</strong><span>A creature entering a space triggers this object or terrain feature.</span></div></div></div><p class=\"legend-note\">These symbols come directly from the Draw Steel source text. Ability type and action timing are also shown in each ability's keyword/action table immediately below the title.</p></div>";

/* Lazily builds the legend panel + backdrop on first use, exactly like the
   existing xrefPreview pattern elsewhere in this file -- this file's script
   tag runs before this HTML would otherwise appear in the document, so it
   must be constructed and appended to document.body rather than expected
   to already exist. */
function ensureIconLegendDOM() {
  if (document.getElementById('iconLegendPanel')) return;
  const backdrop = document.createElement('div');
  backdrop.id = 'legendBackdrop';
  backdrop.className = 'panel-backdrop';
  const panel = document.createElement('aside');
  panel.id = 'iconLegendPanel';
  panel.className = 'slide-panel';
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-modal', 'true');
  panel.setAttribute('aria-label', 'Ability icon legend');
  panel.innerHTML = ICON_LEGEND_FRAGMENT;
  document.body.appendChild(backdrop);
  document.body.appendChild(panel);
  document.getElementById('legendCloseBtn').onclick = closeIconLegend;
  backdrop.onclick = closeIconLegend;
  panel.addEventListener('keydown', e => { if (e.key === 'Escape') closeIconLegend(); });
}

function openIconLegend() {
  ensureIconLegendDOM();
  document.getElementById('iconLegendPanel').classList.add('open');
  document.getElementById('legendBackdrop').classList.add('open');
  document.getElementById('legendCloseBtn').focus();
}
function closeIconLegend() {
  document.getElementById('iconLegendPanel')?.classList.remove('open');
  document.getElementById('legendBackdrop')?.classList.remove('open');
}

document.getElementById('legendBtn').onclick = openIconLegend;

/* Inject tooltip spans around ability-icon characters in freshly-rendered
   record bodies (called from wireDetail once per record render). */
function wrapIconTips(container) {
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) {
    const parent = node.parentElement;
    if (!parent || parent.closest('a,button,code,pre,script,style,.icon-tip')) continue;
    const text = node.nodeValue;
    let changed = false;
    const parts = [];
    let last = 0;
    let i = 0;
    while (i < text.length) {
      let matched = null;
      if (i + 2 <= text.length && ICON_TIP_MAP[text.slice(i, i + 2)]) {
        matched = { icon: text.slice(i, i + 2), len: 2 };
      } else if (i + 1 <= text.length && ICON_TIP_MAP[text.slice(i, i + 1)]) {
        matched = { icon: text.slice(i, i + 1), len: 1 };
      }
      if (matched) {
        if (i > last) parts.push(document.createTextNode(text.slice(last, i)));
        const span = document.createElement('span');
        span.className = 'icon-tip';
        span.setAttribute('data-tip', matched.icon + ' ' + ICON_TIP_MAP[matched.icon]);
        span.setAttribute('tabindex', '0');
        span.textContent = matched.icon;
        parts.push(span);
        last = i + matched.len;
        i += matched.len;
        changed = true;
      } else {
        i++;
      }
    }
    if (changed) {
      if (last < text.length) parts.push(document.createTextNode(text.slice(last)));
      const frag = document.createDocumentFragment();
      parts.forEach(p => frag.appendChild(p));
      node.replaceWith(frag);
    }
  }
}


