function lessonToolLinkHTML(lessonId) {
  const entry = LESSON_TOOL_MAP[lessonId];
  if (!entry) return '';
  return `<section class="learning-section lesson-tool-link"><header class="learning-section-head"><h3>Interactive tool</h3><span>Practice what you learned</span></header><div class="tool-link-card"><p>${esc(entry.detail)}</p><button class="director-btn primary" data-lesson-tool="${esc(entry.tab)}" data-from-lesson="${esc(lessonId)}">${esc(entry.label)}</button></div></section>`;
}

function wireLessonToolLinks() {
  document.querySelectorAll('[data-lesson-tool]').forEach(btn => {
    btn.onclick = () => {
      state.returnToLesson = btn.dataset.fromLesson;
      openDirectorTools(btn.dataset.lessonTool);
    };
  });
}


