function kitBodySection(body,heading,nextHeading){const start=String(body||'').search(new RegExp(`^#####\\s+${heading}\\s*$`,'mi'));if(start<0)return '';const after=String(body).slice(start).replace(/^#####.*\n?/,'');const end=nextHeading?after.search(new RegExp(`^#####\\s+${nextHeading}\\s*$`,'mi')):-1;return (end<0?after:after.slice(0,end)).trim();}
