  const maximum=key=>Math.max(0,...rules.map(rule=>Number(rule[key])||0)),damage=key=>[0,1,2].map(index=>Math.max(0,...rules.map(rule=>Number(rule[key]?.[index])||0)));
  return {staminaPerEchelon:maximum('staminaPerEchelon'),speed:maximum('speed'),stability:maximum('stability'),meleeDamage:damage('meleeDamage'),rangedDamage:damage('rangedDamage'),meleeDistance:maximum('meleeDistance'),rangedDistance:maximum('rangedDistance'),disengage:maximum('disengage')};
