function compareValidationSnapshots(previous,current,fromVersion=state.previousContentVersion,toVersion=CONTENT_VERSION) {
  const heroes=[...new Set([...Object.keys(previous||{}),...Object.keys(current||{})])].map(id=>{
    const before=new Set(previous?.[id]?.findings||[]),after=new Set(current?.[id]?.findings||[]);
    return {id,name:current?.[id]?.name||previous?.[id]?.name||id,added:[...after].filter(item=>!before.has(item)),cleared:[...before].filter(item=>!after.has(item))};
  }).filter(hero=>hero.added.length||hero.cleared.length);
  return {schema:'draw-steel-content-migration-report-v1',fromVersion:fromVersion||'first-run',toVersion,generatedAt:new Date().toISOString(),changed:!!fromVersion&&fromVersion!==toVersion,heroes,totals:{heroesReviewed:Object.keys(current||{}).length,heroesChanged:heroes.length,addedFindings:heroes.reduce((sum,hero)=>sum+hero.added.length,0),clearedFindings:heroes.reduce((sum,hero)=>sum+hero.cleared.length,0)}};
}
function initializeContentMigration() {
  const current=heroValidationSnapshot();
  state.contentMigrationReport=compareValidationSnapshots(state.previousValidationSnapshot,current);
  store.set('contentVersion',CONTENT_VERSION);
  store.set('contentSha256',CONTENT_SHA256);
  store.set('heroValidationSnapshot',current);
}
