  if(set.career){const quick=set.career.quickSkills.map(name=>SKILL_BY_NAME.get(normalize(name))).filter(Boolean);set.career.skillDefinitions.forEach(definition=>{const skill=quick.find(item=>!used.has(item.id)&&choiceOption(definition,item.id));if(skill){setBackgroundChoiceAnswer(hero,definition,{selectedIds:[skill.id]},`Quick Build: ${skill.name}`);used.add(skill.id);}});if(set.career.perkDefinition&&set.career.quickPerk){const perk=set.career.perkDefinition.options.find(option=>normalize(option.name)===normalize(set.career.quickPerk));if(perk)setBackgroundChoiceAnswer(hero,set.career.perkDefinition,{selectedIds:[perk.id]},`Quick Build: ${perk.name}`);}}
  set.culture.forEach(item=>{const skill=SKILL_BY_NAME.get(normalize(item.quickSkill));if(skill&&!used.has(skill.id)&&choiceOption(item.definition,skill.id)){setBackgroundChoiceAnswer(hero,item.definition,{selectedIds:[skill.id]},`Quick Build: ${skill.name}`);used.add(skill.id);}});
