function culturePreviewHTML(hero) {
  const parts = [];
  [['Environment', hero.cultureEnvironment], ['Organization', hero.cultureOrganization], ['Upbringing', hero.cultureUpbringing]].forEach(([aspect, slug]) => {
    if (!slug) return;
    const opt = cultureOption(aspect, slug);
    if (opt) parts.push(`<div><strong>${esc(aspect)} — ${esc(opt.name)}:</strong> ${esc(opt.skillOptions || 'See culture rules.')}</div>`);
  });
  if (!parts.length) return '';
  return previewBox('Culture Skill Options', parts.join(''));
}

