  return `<section class="complication-builder"><div class="complication-head"><div><strong>${esc(values.name)}</strong><div class="complication-status ${values.valid?'complete':'incomplete'}">${values.valid?'Complete':`${values.issues.length} decision${values.issues.length===1?'':'s'} remaining`}</div></div><button class="mini-btn" data-open-source="${esc(hero.complicationId)}">Full source</button></div><div class="complication-panels"><div class="complication-panel"><strong>Benefit</strong><p>${complicationRuleTextHTML(values.benefit)}</p></div><div class="complication-panel drawback"><strong>Drawback or restriction</strong><p>${complicationRuleTextHTML(values.drawback)}</p></div></div>${values.cultureSuppressed?'<div class="choice-warning"><strong>Creation rule changed:</strong> Raised by Beasts replaces culture benefits. Culture language and aspect skill choices are ignored while this complication is selected.</div>':''}${definitions.length?`<div class="choice-section-label">Required complication decisions <span>${definitions.length}</span></div><div class="complication-choice-grid">${definitions.map(definition=>complicationChoiceHTML(definition,hero)).join('')}</div>`:'<div class="complication-status complete">This complication has no nested decisions.</div>'}<div class="complication-summary"><div><strong>Applied package:</strong> ${summary.length?esc(summary.join(' · ')):'Narrative or conditional effects shown above'}</div>${values.choiceSummaries.filter(item=>item.names.length).map(item=>`<div><strong>${esc(item.prompt)}:</strong> ${esc(item.names.join(', '))}</div>`).join('')}</div>${values.issues.length?`<details class="background-issues"><summary>${values.issues.length} unresolved complication decision${values.issues.length===1?'':'s'}</summary>${values.issues.map(issue=>`<p>${esc(issue)}</p>`).join('')}</details>`:''}</section>`;
