  return `<div class="inline-preview kit-engine"><div class="kit-engine-head"><div class="kit-engine-title"><strong>${esc(values.kits.map(kit=>kit.name).join(' + '))}</strong><span>Kit engine · Echelon ${values.echelon}</span></div>${values.kits.map(kit=>`<button class="mini-btn" data-open-source="${esc(kit.id)}">${esc(kit.name)} source</button>`).join('')}</div><div class="kit-stat-grid"><div class="kit-stat"><strong>${values.baseStamina} → ${values.stamina}</strong><span>Stamina${values.kitStaminaBonus?` · +${values.kitStaminaBonus}`:''}</span></div><div class="kit-stat"><strong>${values.baseSpeed} → ${values.speed}</strong><span>Speed</span></div><div class="kit-stat"><strong>${values.baseStability} → ${values.stability}</strong><span>Stability</span></div><div class="kit-stat"><strong>${values.disengageDistance}</strong><span>Disengage shift</span></div></div><div><strong>Applied modifiers:</strong> ${esc(modifierParts.join(' · ')||'No numerical modifiers')}</div>${values.kits.length>1?`<div class="kit-stack-note">Shared benefits use the higher bonus, following Field Arsenal; they do not stack.</div>`:''}<div class="kit-equipment"><strong>Equipment requirements</strong>${values.equipment.map(item=>`<div class="kit-row"><div><strong>${esc(item.kitName)}</strong><p>${esc(item.description)}</p></div><span class="background-chip">${esc(item.armor==='none'?'No armor':`${item.armor} armor`)}</span></div>`).join('')}</div><div class="free-strike-grid">${strikeHTML('melee',values.freeStrikes.melee)}${strikeHTML('ranged',values.freeStrikes.ranged)}</div><div class="kit-abilities"><strong>Automatically granted signature ${values.abilityIds.length===1?'ability':'abilities'}</strong>${values.abilityIds.map(id=>{const ability=RECORD_BY_ID.get(id);return `<div class="kit-row"><div><strong>${esc(ability.name)}</strong><p>${esc(plainText(ability.summary||ability.body).slice(0,220))}${plainText(ability.summary||ability.body).length>220?'…':''}</p></div><button class="mini-btn" data-open-source="${esc(id)}">Open ability</button></div>`;}).join('')}</div></div>`;
