  return (async()=>{const results=[];try{for(const fixture of fixtures){await new Promise(resolve=>setTimeout(resolve,0));try{const detail=await fixture.run();results.push({name:fixture.name,passed:true,detail:detail||''});}catch(error){results.push({name:fixture.name,passed:false,detail:error.message});}}return {passed:results.every(result=>result.passed),total:results.length,failures:results.filter(result=>!result.passed).length,results};}finally{SELF_TEST_ACTIVE=previousTestState;}})();
